    /// #69: the faint glow of the selected card's yellow frame (the design's 12 px blur: SwiftUI's radius is half a CSS blur). No offset shadows in the window
    public static let selectionGlow = ShadowToken(color: Palette.yellow.opacity(0.45), radius: 6, x: 0, y: 0)
    /// the Needs-check panel's glow under its yellow top line
    public static let checkGlow = ShadowToken(color: Palette.yellow.opacity(0.25), radius: 6, x: 0, y: 0)
    /// the yellow + under the pointer
    public static let plusGlow = ShadowToken(color: Palette.yellow.opacity(0.6), radius: 4, x: 0, y: 0)
    /// #72: the state pill's soft shadow (CSS 0 1 3; SwiftUI's radius is about half the CSS blur)
    public static let statePill = ShadowToken(color: Palette.ink.opacity(0.18), radius: 1.5, x: 0, y: 1)
    /// the selected mission card's soft shadow (CSS 0 2 10)
    public static let missionSelected = ShadowToken(color: Palette.ink.opacity(0.1), radius: 5, x: 0, y: 2)
    /// a mission card under the pointer (CSS 0 1 6)
    public static let missionHover = ShadowToken(color: Palette.ink.opacity(0.08), radius: 3, x: 0, y: 1)
}

/// `motion`: an `Animation` where the token has a curve, else a `Duration` to wait (a value settling).
public enum Motion {
    /// the section panel and terminal show/hide
    public static let panel = Animation.easeInOut(duration: 0.3)
    /// settledWidth
    public static let settle = Duration.milliseconds(150)
    /// the drop feedback appearing (user-driven), new tray thumbnails
    public static let dropIn = Animation.easeOut(duration: 0.18)
    /// the drop feedback leaving
    public static let dropOut = Animation.easeIn(duration: 0.12)
}

/// `font.family`: the bundled families (Resources/Fonts, SIL OFL 1.1).
public enum FontFamily: String, CaseIterable, Sendable {
    case ui = "Inter"
    case mono = "JetBrains Mono"

    /// PostScript names of the bundled faces, by weight.
    var faces: [Int: String] {
        switch self {
        case .ui: [400: "Inter-Regular", 500: "Inter-Medium", 600: "Inter-SemiBold", 700: "Inter-Bold", 800: "Inter-ExtraBold", 900: "Inter-Black"]
        case .mono: [400: "JetBrainsMono-Regular", 500: "JetBrainsMono-Medium", 600: "JetBrainsMono-SemiBold", 700: "JetBrainsMono-Bold"]
        }
    }
}

/// `font.role`: the type roles (`View.typeRole(_:)`).
public enum TypeRole: CaseIterable, Sendable {
    case heading, title, headline, body, callout, caption, label, button, quietTitle, detailTitle, trackedLabel, columnLabel, count, tag, controlLabel, micro, missionTitle, message, statePill, mono, monoSmall

    public var spec: TypeSpec {
        switch self {
        case .heading: TypeSpec(family: .ui, size: 15, weight: 700, tracking: 0.6, uppercase: true)
        case .title: TypeSpec(family: .ui, size: 15, weight: 600, tracking: 0, uppercase: false)
        case .headline: TypeSpec(family: .ui, size: 13, weight: 600, tracking: 0, uppercase: false)
        case .body: TypeSpec(family: .ui, size: 13, weight: 400, tracking: 0, uppercase: false)
        case .callout: TypeSpec(family: .ui, size: 12, weight: 400, tracking: 0, uppercase: false)
        case .caption: TypeSpec(family: .ui, size: 11, weight: 400, tracking: 0, uppercase: false)
        case .label: TypeSpec(family: .ui, size: 10, weight: 600, tracking: 0.8, uppercase: true)
        case .button: TypeSpec(family: .ui, size: 12, weight: 600, tracking: 0.3, uppercase: false)
        case .quietTitle: TypeSpec(family: .ui, size: 13, weight: 500, tracking: 0, uppercase: false)
        case .detailTitle: TypeSpec(family: .ui, size: 14, weight: 600, tracking: 0, uppercase: false)
        case .trackedLabel: TypeSpec(family: .ui, size: 10, weight: 600, tracking: 1.4, uppercase: true)
        case .columnLabel: TypeSpec(family: .ui, size: 11, weight: 600, tracking: 1.54, uppercase: true)
        case .count: TypeSpec(family: .ui, size: 28, weight: 500, tracking: -0.56, uppercase: false)
        case .tag: TypeSpec(family: .ui, size: 10, weight: 600, tracking: 1, uppercase: true)
        case .controlLabel: TypeSpec(family: .ui, size: 10, weight: 600, tracking: 1.2, uppercase: true)
        case .micro: TypeSpec(family: .ui, size: 10, weight: 500, tracking: 0, uppercase: false)
        case .missionTitle: TypeSpec(family: .ui, size: 14, weight: 500, tracking: 0, uppercase: false)
        case .message: TypeSpec(family: .ui, size: 14, weight: 400, tracking: 0, uppercase: false)
        case .statePill: TypeSpec(family: .ui, size: 11, weight: 600, tracking: 0, uppercase: false)
        case .mono: TypeSpec(family: .mono, size: 12, weight: 400, tracking: 0, uppercase: false)
        case .monoSmall: TypeSpec(family: .mono, size: 11, weight: 400, tracking: 0, uppercase: false)
        }
    }
}
